/**
 * pipeline/personal-publisher.ts — SoloHub 个人发布
 *
 * 将 BlueprintDTO 序列化为 Synova.yml 并写入 SoloHub 目录结构。
 * 纯文件 I/O，无 LLM 调用，同步返回。
 *
 * SoloHub 目录结构：
 *   ~/.solohub/
 *   ├── manifest.json
 *   ├── agents/{blueprintId}/
 *   │   ├── synova.yml
 *   │   ├── blueprint.json
 *   │   └── agents/{agentName}/
 *   │       ├── SOUL.md
 *   │       ├── TOOLS.md
 *   │       └── HEARTBEAT.md
 */
import type { BlueprintDTO } from '../types';
export interface PublishOptions {
    /** SoloHub 根目录，默认 ~/.solohub */
    solohubDir?: string;
    /** 是否覆盖已有发布 */
    overwrite?: boolean;
}
export interface PublishResult {
    status: 'published' | 'updated';
    blueprintId: string;
    solohubPath: string;
    synovaYml: string;
    agentsCount: number;
}
export interface ManifestEntry {
    blueprintId: string;
    name: string;
    publishedAt: string;
    updatedAt: string;
    agentCount: number;
    agentsDir: string;
}
export interface SoloHubManifest {
    version: string;
    updatedAt: string;
    agents: ManifestEntry[];
}
/**
 * Publish a BlueprintDTO to the SoloHub personal directory.
 *
 * Writes:
 *   - synova.yml (human-readable YAML)
 *   - blueprint.json (full machine-readable BlueprintDTO)
 *   - agents/{roleName}/SOUL.md, TOOLS.md, HEARTBEAT.md
 *   - Updates ~/.solohub/manifest.json
 *
 * Idempotent: re-publishing the same blueprintId updates the files in place.
 */
export declare function publishToPersonal(blueprint: BlueprintDTO, options?: PublishOptions): PublishResult;
/**
 * List all agents published to SoloHub.
 */
export declare function listPublishedAgents(solohubDir?: string): ManifestEntry[];
/**
 * Get a single published agent by blueprintId.
 */
export declare function getPublishedAgent(blueprintId: string, solohubDir?: string): {
    entry: ManifestEntry;
    synovaYml: string;
    blueprint: BlueprintDTO;
} | null;
